"""Report cards per stream / per class, generated by each class teacher, printed in bulk.
bench --site <site> run-tests --module school_erp.tests.test_report_cards_per_stream"""

import os

import frappe

from school_erp.tests.test_integration import TestCase, setup_school

CLS = "Grade 5"
TEACHER = "rc.classteacher@test.school"


class TestReportCardsPerStream(TestCase):
	@classmethod
	def setUpClass(cls):
		super().setUpClass()
		setup_school(cls)
		frappe.set_user("Administrator")
		tag = frappe.generate_hash(length=4)
		cls.east, cls.west = (cls._stream(f"RC{tag} East"), cls._stream(f"RC{tag} West"))
		if not frappe.db.exists("User", TEACHER):
			frappe.get_doc({"doctype": "User", "email": TEACHER, "first_name": "Class", "last_name": "Teacher",
							"send_welcome_email": 0}).insert(ignore_permissions=True)
		frappe.get_doc("User", TEACHER).add_roles("Teacher")
		teacher = frappe.db.get_value("Teacher", {"user": TEACHER}) or frappe.get_doc(
			{"doctype": "Teacher", "teacher_name": "Class Teacher RC", "user": TEACHER}).insert().name
		frappe.db.set_value("Stream", cls.east, "class_teacher", teacher)
		cls.students = {s: [cls._student(s, n) for n in ("One", "Two")] for s in (cls.east, cls.west)}
		if not frappe.db.exists("Subject", "Mathematics"):
			frappe.get_doc({"doctype": "Subject", "subject_name": "Mathematics"}).insert()
		cls.exam = frappe.get_doc({"doctype": "Exam", "exam_name": f"RC Stream Test {tag}", "school_term": cls.term,
								   "grading_scale": "KCSE (8-4-4)", "max_marks": 100, "classes": [{"school_class": CLS}],
								   "subjects": [{"subject": "Mathematics"}]}).insert().name
		frappe.db.commit()

	@classmethod
	def tearDownClass(cls):
		frappe.set_user("Administrator")
		cls._pub.stop()
		super().tearDownClass()

	@staticmethod
	def _stream(name):
		if not frappe.db.exists("Stream", f"{CLS} {name}"):
			frappe.get_doc({"doctype": "Stream", "school_class": CLS, "stream_name": name}).insert()
		return f"{CLS} {name}"

	@staticmethod
	def _student(stream, first):
		return frappe.get_doc({"doctype": "Student", "first_name": first, "last_name": stream.split()[-1], "stream": stream,
							   "gender": "Female", "guardians": [{"guardian_name": "Mama", "relation": "Mother",
																	"mobile_no": "0712345678", "is_primary": 1}]}).insert().name

	def setUp(self):
		frappe.set_user("Administrator")

	def _sheet(self, stream, marks):
		from school_erp.demo import _approve_marks

		ms = frappe.get_doc({"doctype": "Exam Mark Sheet", "exam": self.exam, "stream": stream, "subject": "Mathematics"})
		ms.get_students()
		for m in ms.marks:
			if m.student in marks:
				m.marks = marks[m.student]
		ms.insert()
		_approve_marks(ms)

	def _cards(self, stream):
		return {r.student: r for r in frappe.get_all("Report Card", filters={"exam": self.exam, "stream": stream},
													  fields=["student", "stream_position", "class_position", "class_size"])}

	def test_class_teacher_generates_and_prints_own_stream(self):
		from school_erp.api import exams

		e1, e2 = self.students[self.east]
		w1, w2 = self.students[self.west]
		self._sheet(self.east, {e1: "90", e2: "50"})

		frappe.set_user(TEACHER)
		opts = exams.report_card_options(self.exam)
		self.assertFalse(opts["manager"])
		self.assertEqual([r["stream"] for r in opts["streams"]], [self.east])  # only their own stream
		with self.assertRaises(frappe.PermissionError):
			exams.generate_report_cards(self.exam, stream=self.west)
		with self.assertRaises(frappe.PermissionError):
			exams.generate_report_cards(self.exam)  # the whole exam is for the Head Teacher / Admin
		with self.assertRaises(frappe.PermissionError):
			exams.generate_report_cards(self.exam, school_class=CLS)  # the class includes West

		out = exams.generate_report_cards(self.exam, stream=self.east)
		self.assertEqual((out["report_cards"], out["streams"]), (2, [self.east]))
		east = self._cards(self.east)
		self.assertEqual((east[e1].stream_position, east[e1].class_position, east[e1].class_size), (1, 1, 2))
		self.assertFalse(self._cards(self.west))  # nothing made for West

		names = exams.bulk_report_card_names(self.exam, stream=self.east)
		self.assertEqual(len(names), 2)
		with self.assertRaises(frappe.PermissionError):
			exams.bulk_report_card_names(self.exam, stream=self.west)
		if os.path.exists(frappe.get_site_path("..", "assets", "assets.json")):  # PDF engine needs built assets
			self.assertTrue(exams.report_cards_pdf(names).startswith(b"%PDF"))

		# West's marks come in; the Head Teacher / Admin generates West: East's class positions move with it
		frappe.set_user("Administrator")
		self._sheet(self.west, {w1: "70", w2: "95"})
		self.assertEqual(exams.generate_report_cards(self.exam, stream=self.west)["report_cards"], 2)
		west, east = self._cards(self.west), self._cards(self.east)
		self.assertEqual((west[w2].class_position, west[w2].class_size), (1, 4))
		self.assertEqual((east[e1].class_position, east[e1].class_size), (2, 4))  # refreshed, not regenerated
		self.assertEqual(east[e1].stream_position, 1)

		# a manager may do the whole class or exam at once
		self.assertEqual(exams.generate_report_cards(self.exam, school_class=CLS)["report_cards"], 4)
		self.assertEqual(len(exams.bulk_report_card_names(self.exam, school_class=CLS)), 4)
